// FSRS-5 spaced-repetition scheduling for LODVault flashcards.
//
// The memory model (stability S in days, difficulty D in 1..10, retrievability
// R) follows FSRS-5 with its 19 default weights, copied from ts-fsrs 4.7.1
// (`default_w`), and rounds intermediate values the way ts-fsrs does, so test
// vectors generated by ts-fsrs match exactly. There is no optimizer: every
// learner uses the defaults.
//
// Scheduling on top of the model is LODVault's own:
// - A new word is learned in steps within the session: it graduates after two
//   correct answers (Easy graduates at once), with S = S0(last grade).
// - A forgotten review card (Again) relearns with one step, then continues
//   from its reduced stability.
// - Intervals get a small deterministic fuzz and are moved to the least
//   loaded day within the fuzz range.
//
// Pure functions only: no storage, no DOM. Exposed as globalThis.LodVaultSrs.
(() => {
  const VERSION = "FSRS-5 (ts-fsrs 4.7.1 default weights)";
  const W = Object.freeze([
    0.40255, 1.18385, 3.173, 15.69105, 7.1949, 0.5345, 1.4604, 0.0046, 1.54575, 0.1192,
    1.01925, 1.9395, 0.11, 0.29605, 2.2698, 0.2315, 2.9898, 0.51655, 0.6621
  ]);
  const DECAY = -0.5;
  const FACTOR = 19 / 81;
  const S_MIN = 0.01;
  const S_MAX = 36500;
  const DAY_MS = 24 * 60 * 60 * 1000;
  const MINUTE_MS = 60 * 1000;

  const GRADES = Object.freeze({ AGAIN: 1, HARD: 2, GOOD: 3, EASY: 4 });
  const STATES = Object.freeze({ NEW: 0, LEARNING: 1, REVIEW: 2, RELEARNING: 3 });
  const LEARNING_STEPS = 2;
  const RELEARNING_STEPS = 1;
  const STEP_DELAY_MINUTES = 10;
  const DEFAULT_RETENTION = 0.9;
  const DEFAULT_MAX_INTERVAL = 365;
  const KNOWN_STABILITY = 7;

  const round8 = (value) => +value.toFixed(8);
  const clamp = (value, min, max) => Math.min(Math.max(value, min), max);

  function forgettingCurve(elapsedDays, stability) {
    return round8(Math.pow(1 + FACTOR * elapsedDays / stability, DECAY));
  }

  function initStability(grade) {
    return Math.max(W[grade - 1], 0.1);
  }

  function constrainDifficulty(difficulty) {
    return Math.min(Math.max(round8(difficulty), 1), 10);
  }

  function initDifficulty(grade) {
    return constrainDifficulty(W[4] - Math.exp((grade - 1) * W[5]) + 1);
  }

  function nextDifficulty(difficulty, grade) {
    const delta = -W[6] * (grade - 3);
    const damped = difficulty + round8(delta * (10 - difficulty) / 9);
    return constrainDifficulty(round8(W[7] * initDifficulty(GRADES.EASY) + (1 - W[7]) * damped));
  }

  function nextRecallStability(difficulty, stability, retrievability, grade) {
    const hardPenalty = grade === GRADES.HARD ? W[15] : 1;
    const easyBonus = grade === GRADES.EASY ? W[16] : 1;
    return round8(clamp(
      stability * (1 + Math.exp(W[8]) * (11 - difficulty) * Math.pow(stability, -W[9])
        * (Math.exp((1 - retrievability) * W[10]) - 1) * hardPenalty * easyBonus),
      S_MIN,
      S_MAX
    ));
  }

  function nextForgetStability(difficulty, stability, retrievability) {
    return round8(clamp(
      W[11] * Math.pow(difficulty, -W[12]) * (Math.pow(stability + 1, W[13]) - 1)
        * Math.exp((1 - retrievability) * W[14]),
      S_MIN,
      S_MAX
    ));
  }

  function nextShortTermStability(stability, grade) {
    return round8(clamp(stability * Math.exp(W[17] * (grade - 3 + W[18])), S_MIN, S_MAX));
  }

  // Stability after a lapse, as ts-fsrs's review state computes it.
  function lapseStability(difficulty, stability, retrievability) {
    const forget = nextForgetStability(difficulty, stability, retrievability);
    return clamp(round8(stability / Math.exp(W[17] * W[18])), S_MIN, forget);
  }

  // ts-fsrs `next_state`: the memory state after one review, elapsedDays after
  // the previous one. Same-day reviews use the short-term formula.
  function nextMemory(memory, elapsedDays, grade) {
    const difficulty = memory?.d || 0;
    const stability = memory?.s || 0;
    if (!difficulty && !stability) {
      return { d: initDifficulty(grade), s: initStability(grade) };
    }
    const retrievability = forgettingCurve(elapsedDays, stability);
    let next = nextRecallStability(difficulty, stability, retrievability, grade);
    if (grade === GRADES.AGAIN) next = lapseStability(difficulty, stability, retrievability);
    if (elapsedDays === 0) next = nextShortTermStability(stability, grade);
    return { d: nextDifficulty(difficulty, grade), s: next };
  }

  function intervalModifier(retention = DEFAULT_RETENTION) {
    return round8((Math.pow(retention, 1 / DECAY) - 1) / FACTOR);
  }

  function nextInterval(stability, retention = DEFAULT_RETENTION, maxInterval = DEFAULT_MAX_INTERVAL) {
    return Math.min(Math.max(1, Math.round(stability * intervalModifier(retention))), maxInterval);
  }

  // Deterministic randomness: the same card at the same review count always
  // gets the same fuzz, on every device and in previews.
  function seededRandom(seedText) {
    let hash = 2166136261;
    for (const char of String(seedText)) {
      hash ^= char.codePointAt(0);
      hash = Math.imul(hash, 16777619) >>> 0;
    }
    let state = hash || 1;
    state = (state + 0x6d2b79f5) >>> 0;
    let value = Math.imul(state ^ (state >>> 15), 1 | state);
    value = (value + Math.imul(value ^ (value >>> 7), 61 | value)) ^ value;
    return ((value ^ (value >>> 14)) >>> 0) / 4294967296;
  }

  // ±5% for intervals up to a week, ±10% up to a month, ±5% beyond.
  // Intervals under three days are never fuzzed.
  function fuzzDelta(days) {
    if (days < 3) return 0;
    const share = days <= 7 ? 0.05 : days <= 30 ? 0.1 : 0.05;
    return Math.max(days >= 7 ? 1 : 0, Math.round(days * share));
  }

  function fuzzInterval(cardId, reps, days, maxInterval = DEFAULT_MAX_INTERVAL) {
    const delta = fuzzDelta(days);
    if (!delta) return Math.min(days, maxInterval);
    const offset = Math.round((seededRandom(`${cardId}:${reps}`) * 2 - 1) * delta);
    return clamp(days + offset, 1, maxInterval);
  }

  // Fuzz, then move to the least loaded day within the fuzz range, so a batch
  // of words learned together doesn't come back on the same day. `load(day)`
  // is how many cards are already due `day` days from today.
  function scheduleDays(cardId, reps, days, options = {}) {
    const maxInterval = options.maxInterval || DEFAULT_MAX_INTERVAL;
    if (options.fuzz === false) return Math.min(days, maxInterval);
    const target = fuzzInterval(cardId, reps, days, maxInterval);
    const delta = fuzzDelta(days);
    if (!delta || typeof options.load !== "function") return target;
    let best = target;
    let bestLoad = Infinity;
    const low = Math.max(1, days - delta);
    const high = Math.min(maxInterval, days + delta);
    for (let day = low; day <= high; day += 1) {
      const load = Number(options.load(day)) || 0;
      if (load < bestLoad || (load === bestLoad && Math.abs(day - target) < Math.abs(best - target))) {
        best = day;
        bestLoad = load;
      }
    }
    return best;
  }

  function toTime(value) {
    if (value instanceof Date) return value.getTime();
    if (typeof value === "number") return value;
    const parsed = Date.parse(value || "");
    return Number.isFinite(parsed) ? parsed : NaN;
  }

  function localDayStart(time) {
    const day = new Date(time);
    day.setHours(0, 0, 0, 0);
    return day.getTime();
  }

  // Whole calendar days between two times, in the learner's time zone.
  function elapsedDays(fromTime, toTimeValue) {
    if (!Number.isFinite(fromTime) || !Number.isFinite(toTimeValue)) return 0;
    return Math.max(0, Math.round((localDayStart(toTimeValue) - localDayStart(fromTime)) / DAY_MS));
  }

  function initCard() {
    return { s: 0, d: 0, st: STATES.NEW, step: 0, lapses: 0, reps: 0, last: null };
  }

  function normalizeCard(card = {}) {
    const st = [0, 1, 2, 3].includes(card?.st) ? card.st : STATES.NEW;
    return {
      s: Number(card?.s) > 0 ? Number(card.s) : 0,
      d: Number(card?.d) > 0 ? clamp(Number(card.d), 1, 10) : 0,
      st,
      step: Math.max(0, Math.floor(Number(card?.step) || 0)),
      lapses: Math.max(0, Math.floor(Number(card?.lapses) || 0)),
      reps: Math.max(0, Math.floor(Number(card?.reps) || 0)),
      last: card?.last ?? null
    };
  }

  function retrievability(card, now = Date.now()) {
    const current = normalizeCard(card);
    const last = toTime(current.last);
    if (current.st === STATES.NEW || !current.s || !Number.isFinite(last)) return null;
    const days = Math.max(0, (toTime(now) - last) / DAY_MS);
    return forgettingCurve(days, current.s);
  }

  function stepResult(card, nowTime) {
    return { card, days: 0, minutes: STEP_DELAY_MINUTES, dueTime: nowTime + STEP_DELAY_MINUTES * MINUTE_MS };
  }

  function reviewResult(card, days, nowTime) {
    return { card, days, minutes: 0, dueTime: localDayStart(nowTime) + days * DAY_MS };
  }

  // Intervals for Hard/Good/Easy on a review card, ordered Hard < Good < Easy
  // after fuzz and load balancing.
  function reviewIntervals(stabilities, card, options) {
    const { retention, maxInterval, cardId } = options;
    const reps = card.reps + 1;
    const pick = (stability) => scheduleDays(cardId, reps, nextInterval(stability, retention, maxInterval), options);
    let hard = pick(stabilities[GRADES.HARD]);
    let good = pick(stabilities[GRADES.GOOD]);
    let easy = pick(stabilities[GRADES.EASY]);
    hard = Math.min(hard, good);
    good = Math.min(maxInterval, Math.max(good, hard + 1));
    easy = Math.min(maxInterval, Math.max(easy, good + 1));
    return { [GRADES.HARD]: hard, [GRADES.GOOD]: good, [GRADES.EASY]: easy };
  }

  // One graded review. Returns the next card and when it is due:
  // { card, days (0 while in steps), minutes (step delay), dueTime }.
  function review(cardInput, grade, now = Date.now(), options = {}) {
    const g = [1, 2, 3, 4].includes(Number(grade)) ? Number(grade) : GRADES.GOOD;
    const nowTime = toTime(now);
    const opts = {
      retention: options.retention || DEFAULT_RETENTION,
      maxInterval: options.maxInterval || DEFAULT_MAX_INTERVAL,
      cardId: options.cardId || "",
      load: options.load,
      fuzz: options.fuzz
    };
    const card = normalizeCard(cardInput);
    const next = { ...card, reps: card.reps + 1, last: new Date(nowTime).toISOString() };

    if (card.st === STATES.NEW) {
      next.d = initDifficulty(g);
      next.s = initStability(g);
      if (g === GRADES.EASY) {
        next.st = STATES.REVIEW;
        next.step = 0;
        return reviewResult(next, scheduleDays(opts.cardId, next.reps, nextInterval(next.s, opts.retention, opts.maxInterval), opts), nowTime);
      }
      next.st = STATES.LEARNING;
      next.step = g === GRADES.GOOD ? 1 : 0;
      return stepResult(next, nowTime);
    }

    if (card.st === STATES.LEARNING || card.st === STATES.RELEARNING) {
      const relearning = card.st === STATES.RELEARNING;
      next.d = nextDifficulty(card.d || initDifficulty(g), g);
      if (relearning) next.s = nextShortTermStability(card.s || initStability(g), g);
      if (g === GRADES.AGAIN) {
        next.step = 0;
        if (!relearning) next.s = initStability(g);
        return stepResult(next, nowTime);
      }
      if (g === GRADES.HARD) return stepResult(next, nowTime);
      const step = card.step + 1;
      if (g === GRADES.GOOD && step < (relearning ? RELEARNING_STEPS : LEARNING_STEPS)) {
        next.step = step;
        if (!relearning) next.s = initStability(g);
        return stepResult(next, nowTime);
      }
      // Graduation. A new word starts from the stability of its last grade.
      if (!relearning) next.s = initStability(g);
      next.st = STATES.REVIEW;
      next.step = 0;
      return reviewResult(next, scheduleDays(opts.cardId, next.reps, nextInterval(next.s, opts.retention, opts.maxInterval), opts), nowTime);
    }

    // Review card.
    const elapsed = elapsedDays(toTime(card.last), nowTime);
    const r = forgettingCurve(elapsed, card.s);
    if (g === GRADES.AGAIN) {
      next.d = nextDifficulty(card.d, GRADES.AGAIN);
      next.s = lapseStability(card.d, card.s, r);
      next.st = STATES.RELEARNING;
      next.step = 0;
      next.lapses = card.lapses + 1;
      return stepResult(next, nowTime);
    }
    const stabilities = {
      [GRADES.HARD]: nextRecallStability(card.d, card.s, r, GRADES.HARD),
      [GRADES.GOOD]: nextRecallStability(card.d, card.s, r, GRADES.GOOD),
      [GRADES.EASY]: nextRecallStability(card.d, card.s, r, GRADES.EASY)
    };
    const days = reviewIntervals(stabilities, card, opts)[g];
    next.d = nextDifficulty(card.d, g);
    next.s = stabilities[g];
    next.st = STATES.REVIEW;
    next.step = 0;
    return reviewResult(next, days, nowTime);
  }

  // What each grade would do, for the interval labels on the buttons.
  function previewIntervals(card, now = Date.now(), options = {}) {
    const preview = {};
    for (const grade of [1, 2, 3, 4]) {
      const result = review(card, grade, now, options);
      preview[grade] = { days: result.days, minutes: result.minutes, st: result.card.st };
    }
    return preview;
  }

  // "I already know this": straight to review with about a week of stability.
  function markKnown(cardInput, now = Date.now(), options = {}) {
    const card = normalizeCard(cardInput);
    const nowTime = toTime(now);
    const next = {
      ...card,
      d: card.d || initDifficulty(GRADES.EASY),
      s: Math.max(card.s, KNOWN_STABILITY),
      st: STATES.REVIEW,
      step: 0,
      reps: card.reps + 1,
      last: new Date(nowTime).toISOString()
    };
    const days = scheduleDays(options.cardId || "", next.reps, nextInterval(next.s, options.retention, options.maxInterval), options);
    return reviewResult(next, days, nowTime);
  }

  const LEGACY_GRADE = Object.freeze({ 1: GRADES.AGAIN, 2: GRADES.GOOD, 3: GRADES.EASY });

  // Lazy migration of a card scheduled by an older build (rating 1..3, fixed
  // interval growth). With its whole log on hand, the log is replayed with its
  // real gaps; otherwise the state is estimated from the interval and counts.
  // Either way the card is a review card and keeps its existing due date.
  function migrateLegacy(meta = {}) {
    const reviews = (Array.isArray(meta.reviews) ? meta.reviews : [])
      .map((review) => ({ time: toTime(review?.date), grade: Number(review?.grade) || LEGACY_GRADE[review?.rating] || GRADES.GOOD }))
      .filter((review) => Number.isFinite(review.time))
      .sort((left, right) => left.time - right.time);
    const total = Math.max(0, Number(meta.totalReviews) || 0);

    if (total && reviews.length === total) {
      let memory = null;
      let lapses = 0;
      let previous = null;
      for (const { time, grade } of reviews) {
        if (!memory) {
          memory = { d: initDifficulty(grade), s: initStability(grade) };
        } else {
          const elapsed = elapsedDays(previous, time);
          const r = forgettingCurve(elapsed, memory.s);
          if (grade === GRADES.AGAIN) {
            lapses += 1;
            memory = { d: nextDifficulty(memory.d, grade), s: lapseStability(memory.d, memory.s, r) };
          } else {
            memory = { d: nextDifficulty(memory.d, grade), s: nextRecallStability(memory.d, memory.s, r, grade) };
          }
        }
        previous = time;
      }
      return { s: memory.s, d: memory.d, st: STATES.REVIEW, step: 0, lapses, reps: total, last: new Date(previous).toISOString() };
    }

    const hard = Math.max(0, Number(meta.hardCount) || 0);
    const easy = Math.max(0, Number(meta.easyCount) || 0);
    const count = Math.max(1, total);
    const last = toTime(meta.lastReviewedAt);
    return {
      s: Math.max(Number(meta.interval) || 0, 1),
      d: round8(clamp(5 + 1.5 * hard / count - 1.5 * easy / count, 1, 10)),
      st: STATES.REVIEW,
      step: 0,
      lapses: 0,
      reps: total,
      last: Number.isFinite(last) ? new Date(last).toISOString() : null
    };
  }

  globalThis.LodVaultSrs = Object.freeze({
    VERSION,
    WEIGHTS: W,
    GRADES,
    STATES,
    LEARNING_STEPS,
    RELEARNING_STEPS,
    STEP_DELAY_MINUTES,
    DEFAULT_RETENTION,
    DEFAULT_MAX_INTERVAL,
    forgettingCurve,
    initStability,
    initDifficulty,
    nextDifficulty,
    nextRecallStability,
    nextForgetStability,
    nextShortTermStability,
    nextMemory,
    intervalModifier,
    nextInterval,
    fuzzDelta,
    fuzzInterval,
    scheduleDays,
    elapsedDays,
    initCard,
    normalizeCard,
    retrievability,
    review,
    previewIntervals,
    markKnown,
    migrateLegacy
  });
})();
